package org.brightstats.stats;

import java.util.*;
import java.util.concurrent.*;
import java.security.MessageDigest;
import java.nio.*;
import java.nio.charset.StandardCharsets;
import org.apache.commons.math3.linear.*;
import org.apache.commons.math3.distribution.NormalDistribution;

/** Seeded model-based power/precision studies with explicit failed-attempt accounting. */
public final class SemSimulation {
    private SemSimulation(){}
    public enum Distribution { NORMAL, STUDENT_T, SKEWED_EXPONENTIAL }
    public enum Missingness { NONE, MCAR, MAR }
    public enum Uncertainty { MODEL, SANDWICH }
    public record Target(String parameter,double nullValue){public Target{if(parameter==null||parameter.isBlank()||!Double.isFinite(nullValue))throw new IllegalArgumentException("Name a target parameter and a finite null value.");}}
    public record Design(SemModel.Model population,SemModel.Model analysis,int[] sampleSizes,int repetitions,List<Target> targets,Distribution distribution,double studentDegreesOfFreedom,Missingness missingness,double missingRate,int marDriver,double marSlope,Uncertainty uncertainty,double alpha,double desiredPower,long seed,int workers,boolean retainReplicates,FimlSem.Options estimator){
        public Design{Objects.requireNonNull(population);if(analysis==null)analysis=nominal(population);sampleSizes=sampleSizes.clone();targets=List.copyOf(targets);Objects.requireNonNull(distribution);Objects.requireNonNull(missingness);Objects.requireNonNull(uncertainty);Objects.requireNonNull(estimator);if(sampleSizes.length<1||sampleSizes.length>12||Arrays.stream(sampleSizes).anyMatch(n->n<20||n>10000)||Arrays.stream(sampleSizes).distinct().count()!=sampleSizes.length||repetitions<20||(long)repetitions*sampleSizes.length>10000||targets.isEmpty()||targets.size()>12||new HashSet<>(targets.stream().map(Target::parameter).toList()).size()!=targets.size())throw new IllegalArgumentException("Choose unique N values (20–10,000), 20+ repeats, 1–12 distinct targets and at most 10,000 total attempts.");if(population.variables().size()>64||population.observed().length>32||population.parameters().size()>80||!compatible(population,analysis))throw new IllegalArgumentException("Simulation requires matching observed order, fixed entries and named free-parameter locations; at most 64 variables, 32 observed variables and 80 free parameters.");Set<String> labels=new HashSet<>(population.parameters().stream().map(SemModel.Parameter::name).toList());for(var target:targets)if(!labels.contains(target.parameter()))throw new IllegalArgumentException("Unknown simulation target: "+target.parameter());if(!(alpha>0&&alpha<1)||!(desiredPower>0&&desiredPower<1)||!Double.isFinite(studentDegreesOfFreedom)||distribution==Distribution.STUDENT_T&&studentDegreesOfFreedom<=4||!Double.isFinite(missingRate)||missingRate<0||missingRate>.8||missingness==Missingness.NONE&&missingRate!=0||marDriver<0||marDriver>=population.observed().length||missingness==Missingness.MAR&&population.observed().length<2&&missingRate>0||!Double.isFinite(marSlope)||Math.abs(marSlope)>8||workers<1||workers>4)throw new IllegalArgumentException("Invalid distribution, missingness, alpha, power or worker settings.");if(retainReplicates&&(long)repetitions*sampleSizes.length*targets.size()>20000)throw new IllegalArgumentException("Retain at most 20,000 replicate-target records; otherwise use summaries and the deterministic result digest.");}
        @Override public int[] sampleSizes(){return sampleSizes.clone();}
    }
    public record TargetValue(String parameter,double estimate,double standardError,Boolean covered,Boolean rejected){}
    public record Trial(int sampleSize,int replicate,long seed,int informativeRows,int missingCells,boolean converged,boolean locallyIdentified,boolean boundary,String issue,List<TargetValue> targets){public Trial{targets=List.copyOf(targets);}}
    public record Summary(int sampleSize,String parameter,double populationValue,double nullValue,int attempts,int convergedPoints,int usableIntervals,int tested,int failures,double meanInformativeRows,double meanMissingFraction,double meanEstimate,double bias,double rmse,double empiricalStandardDeviation,double meanStandardError,double meanIntervalWidth,double conditionalCoverage,double attemptLevelCoverage,double coverageMonteCarloSE,double conditionalPower,double attemptLevelDetectionRate,double powerMonteCarloSE,double powerLow95,double powerHigh95){}
    public record Recommendation(String parameter,double desiredPower,Integer firstTestedNPointThreshold,Integer firstTestedNLower95Threshold){}
    public record Result(Design design,int effectiveWorkers,int completedAttempts,List<Summary> summaries,List<Recommendation> recommendations,Map<String,Integer> issues,List<Trial> failureExamples,List<Trial> replicates,String replicateResultSha256,List<String> warnings){public Result{summaries=List.copyOf(summaries);recommendations=List.copyOf(recommendations);issues=Map.copyOf(issues);failureExamples=List.copyOf(failureExamples);replicates=List.copyOf(replicates);warnings=List.copyOf(warnings);}}
    record Population(double[][] transform,double[] means,int[] observed,double[] observedSD){}
    public static void validate(Design design){population(design.population());population(design.analysis());}
    public static Result run(Design design,java.util.function.IntConsumer progress){
        Population generator=population(design.population());population(design.analysis());int total=design.sampleSizes().length*design.repetitions(),count=0;Trial[] trials=new Trial[total];int workers=Math.min(design.workers(),Math.max(1,Runtime.getRuntime().availableProcessors()));long q=design.analysis().parameters().size(),v=design.analysis().variables().size(),p=design.analysis().observed().length,maxN=Arrays.stream(design.sampleSizes()).max().orElseThrow(),perWorker=32L*1024*1024+16*maxN*(p+q)+32*q*(p*p+v*v);workers=(int)Math.max(1,Math.min(workers,Math.max(1,Runtime.getRuntime().maxMemory()/2/perWorker)));ExecutorService pool=Executors.newFixedThreadPool(workers,Thread.ofPlatform().daemon().name("brightstats-simulation-",0).factory());List<Future<IndexedTrial>> futures=new ArrayList<>();CompletionService<IndexedTrial> completed=new ExecutorCompletionService<>(pool);
        try{int index=0;for(int n:design.sampleSizes())for(int rep=0;rep<design.repetitions();rep++){Matrices.interrupted();final int slot=index++,repeat=rep,size=n;long seed=mix(design.seed()^((long)n<<32)^rep);futures.add(completed.submit(()->new IndexedTrial(slot,trial(design,generator,size,repeat+1,seed))));}while(count<total){Matrices.interrupted();IndexedTrial value=completed.take().get();trials[value.index()]=value.trial();count++;if(progress!=null)progress.accept(count);}}
        catch(InterruptedException interrupted){Thread.currentThread().interrupt();throw new CancellationException("Simulation cancelled; no partial study is returned.");}
        catch(ExecutionException failure){Throwable cause=failure.getCause();if(cause instanceof CancellationException cancelled)throw cancelled;if(cause instanceof Error error)throw error;throw new IllegalStateException("Simulation worker failed.",cause);}
        finally{for(var future:futures)if(!future.isDone())future.cancel(true);pool.shutdownNow();}
        List<Summary> summaries=new ArrayList<>();Map<String,Integer> issues=new TreeMap<>();List<Trial> examples=new ArrayList<>();for(var trial:trials)if(!trial.issue().isEmpty()){issues.merge(trial.issue(),1,Integer::sum);if(examples.size()<30)examples.add(trial);}for(int n:design.sampleSizes())for(int target=0;target<design.targets().size();target++)summaries.add(summarize(design,trials,n,target));List<Recommendation> recommendations=new ArrayList<>();for(var target:design.targets()){Integer point=null,conservative=null;for(var row:summaries.stream().filter(s->s.parameter().equals(target.parameter())).sorted(Comparator.comparingInt(Summary::sampleSize)).toList()){if(point==null&&row.conditionalPower()>=design.desiredPower())point=row.sampleSize();if(conservative==null&&row.powerLow95()>=design.desiredPower())conservative=row.sampleSize();}recommendations.add(new Recommendation(target.parameter(),design.desiredPower(),point,conservative));}
        List<String> warnings=new ArrayList<>();warnings.add("These are finite model-based simulations, not a guarantee of real-study power, minimum sample size or identification. Recommendations refer only to tested N values; no extrapolation is performed.");warnings.add("Coverage/power are reported conditionally on available intervals/tests and operationally per attempt; failed/nonregular attempts are retained and never replaced. Bias/precision use converged point estimates only. Monte Carlo SE and 95% Wilson power limits describe simulation uncertainty.");warnings.add("Alpha is per target, with no automatic multiple-testing adjustment. Variance/covariance or bound-null targets do not receive generic normal-ratio power tests; their bias/coverage can still be studied.");warnings.add("Population values and analysis starts are separate. Non-normal structural disturbances and MAR/MCAR scenarios stress the selected Gaussian analysis; sandwich covariance does not repair an incorrect mean/covariance/missingness model.");if(design.missingness()==Missingness.MAR)warnings.add("MAR masking keeps the selected driver observed and calibrates the expected missing fraction among other selected variables using its observed values. It does not impose that rate on the driver.");if(workers<design.workers())warnings.add("Worker count was capped by available processors and the conservative heap working-set budget.");return new Result(design,workers,count,summaries,recommendations,issues,examples,design.retainReplicates()?List.of(trials):List.of(),digest(trials),warnings);
    }
    private record IndexedTrial(int index,Trial trial){}
    static Trial trial(Design d,Population generator,int n,int replicate,long seed){Random rng=new Random(seed);double[][] data=new double[n][generator.observed().length];int variables=generator.means().length;for(int row=0;row<n;row++){if((row&31)==0)Matrices.interrupted();double[] noise=new double[variables];double radial=d.distribution()==Distribution.STUDENT_T?Math.sqrt((d.studentDegreesOfFreedom()-2)/(2*GaussianImputation.gamma(d.studentDegreesOfFreedom()/2,rng))):1;for(int j=0;j<variables;j++)noise[j]=d.distribution()==Distribution.SKEWED_EXPONENTIAL?-Math.log1p(-rng.nextDouble())-1:rng.nextGaussian()*radial;for(int j=0;j<data[row].length;j++){int variable=generator.observed()[j];double value=generator.means()[variable];for(int k=0;k<variables;k++)value+=generator.transform()[variable][k]*noise[k];data[row][j]=value;}}
        int missing=mask(data,d,generator,rng);int informative=0;for(var row:data)if(Arrays.stream(row).anyMatch(Double::isFinite))informative++;List<TargetValue> values=new ArrayList<>();try{var fit=FimlSem.fit(data,d.analysis(),d.estimator());List<String> labels=fit.model().parameters().stream().map(SemModel.Parameter::name).toList();double[][] covariance=d.uncertainty()==Uncertainty.MODEL?fit.parameterCovariance():fit.sandwichCovariance();double critical=new NormalDistribution().inverseCumulativeProbability((1+d.estimator().confidence())/2),testCritical=new NormalDistribution().inverseCumulativeProbability(1-d.alpha()/2);boolean allInference=true;for(var target:d.targets()){int index=labels.indexOf(target.parameter());var parameter=fit.model().parameters().get(index);double estimate=fit.estimates()[index],se=Math.sqrt(covariance[index][index]),truth=d.population().parameters().stream().filter(p->p.name().equals(target.parameter())).findFirst().orElseThrow().start();boolean regular=fit.converged()&&fit.locallyIdentified()&&!fit.boundary()&&Double.isFinite(se)&&se>0;allInference&=regular;boolean testable=parameter.locations().stream().noneMatch(l->l.kind()==SemModel.Kind.COVARIANCE)&&(parameter.lower()==null||target.nullValue()>parameter.lower())&&(parameter.upper()==null||target.nullValue()<parameter.upper());values.add(new TargetValue(target.parameter(),fit.converged()?estimate:Double.NaN,regular?se:Double.NaN,regular?Math.abs(estimate-truth)<=critical*se:null,regular&&testable?Math.abs((estimate-target.nullValue())/se)>testCritical:null));}String issue=!fit.converged()?"Optimizer did not converge":!fit.locallyIdentified()?"Information not locally identified":fit.boundary()?"Configured parameter boundary":!allInference?"Target uncertainty unavailable":"";return new Trial(n,replicate,seed,fit.observations(),missing,fit.converged(),fit.locallyIdentified(),fit.boundary(),issue,values);}
        catch(CancellationException interrupted){throw interrupted;}catch(RuntimeException failure){values.clear();for(var target:d.targets())values.add(new TargetValue(target.parameter(),Double.NaN,Double.NaN,null,null));String message=failure.getMessage()==null?failure.getClass().getSimpleName():failure.getMessage();if(message.length()>500)message=message.substring(0,500);return new Trial(n,replicate,seed,informative,missing,false,false,false,message,values);}
    }
    private static int mask(double[][] data,Design d,Population population,Random rng){if(d.missingness()==Missingness.NONE||d.missingRate()==0)return 0;double intercept=0;if(d.missingness()==Missingness.MAR){double low=-50,high=50;int driver=d.marDriver(),variable=population.observed()[driver];for(int iteration=0;iteration<70;iteration++){double middle=(low+high)/2,average=0;for(var row:data)average+=logistic(middle+d.marSlope()*(row[driver]-population.means()[variable])/population.observedSD()[driver])/data.length;if(average<d.missingRate())low=middle;else high=middle;}intercept=(low+high)/2;}int missing=0;for(var row:data){double probability=d.missingness()==Missingness.MCAR?d.missingRate():logistic(intercept+d.marSlope()*(row[d.marDriver()]-population.means()[population.observed()[d.marDriver()]])/population.observedSD()[d.marDriver()]);for(int j=0;j<row.length;j++)if((d.missingness()!=Missingness.MAR||j!=d.marDriver())&&rng.nextDouble()<probability){row[j]=Double.NaN;missing++;}}return missing;}
    private static double logistic(double z){return z>=0?1/(1+Math.exp(-z)):Math.exp(z)/(1+Math.exp(z));}
    private static Summary summarize(Design d,Trial[] trials,int n,int targetIndex){Target target=d.targets().get(targetIndex);double truth=d.population().parameters().stream().filter(p->p.name().equals(target.parameter())).findFirst().orElseThrow().start(),mean=0,ss=0,squaredError=0,sumSE=0,sumWidth=0,informativeRows=0,missingCells=0;int attempts=0,points=0,intervals=0,covered=0,tested=0,rejected=0,failures=0;double critical=new NormalDistribution().inverseCumulativeProbability((1+d.estimator().confidence())/2);for(var trial:trials)if(trial.sampleSize()==n){attempts++;informativeRows+=trial.informativeRows();missingCells+=trial.missingCells();TargetValue value=trial.targets().get(targetIndex);if(value.covered()==null)failures++;if(Double.isFinite(value.estimate())){points++;double delta=value.estimate()-mean;mean+=delta/points;ss+=delta*(value.estimate()-mean);squaredError+=(value.estimate()-truth)*(value.estimate()-truth);}if(value.covered()!=null){intervals++;if(value.covered())covered++;sumSE+=value.standardError();sumWidth+=2*critical*value.standardError();}if(value.rejected()!=null){tested++;if(value.rejected())rejected++;}}double coverage=intervals>0?covered/(double)intervals:Double.NaN,power=tested>0?rejected/(double)tested:Double.NaN;double[] limits=wilson(rejected,tested);return new Summary(n,target.parameter(),truth,target.nullValue(),attempts,points,intervals,tested,failures,informativeRows/attempts,missingCells/(attempts*n*d.population().observed().length),points>0?mean:Double.NaN,points>0?mean-truth:Double.NaN,points>0?Math.sqrt(squaredError/points):Double.NaN,points>1?Math.sqrt(ss/(points-1)):Double.NaN,intervals>0?sumSE/intervals:Double.NaN,intervals>0?sumWidth/intervals:Double.NaN,coverage,covered/(double)attempts,intervals>0?Math.sqrt(coverage*(1-coverage)/intervals):Double.NaN,power,tested>0?rejected/(double)attempts:Double.NaN,tested>0?Math.sqrt(power*(1-power)/tested):Double.NaN,limits[0],limits[1]);}
    private static double[] wilson(int yes,int n){if(n==0)return new double[]{Double.NaN,Double.NaN};double z=1.959963984540054,p=yes/(double)n,denominator=1+z*z/n,center=(p+z*z/(2*n))/denominator,half=z*Math.sqrt(p*(1-p)/n+z*z/(4.0*n*n))/denominator;return new double[]{Math.max(0,center-half),Math.min(1,center+half)};}
    static Population population(SemModel.Model model){int size=model.variables().size(),p=model.observed().length;double[][] identity=new double[p][p];for(int j=0;j<p;j++)identity[j][j]=1;var work=new CovarianceSem.Work(identity,new double[p],model,new CovarianceSem.Options(1000,1e-8,1e-12,CovarianceSem.Likelihood.NORMAL,true,.95));double[] point=model.parameters().stream().mapToDouble(v->v.start()/v.scale()).toArray();var state=work.state(point);if(state==null||!CovarianceSem.properDisturbance(state.disturbance().getData(),state.fullCovariance().getData()))throw new IllegalArgumentException("Population or analysis starting model is inadmissible; specify valid independent analysis starts.");double[][] s=state.disturbance().getData(),normalized=new double[size][size],lower=new double[size][size];double[] sd=new double[size];for(int i=0;i<size;i++)sd[i]=Math.sqrt(Math.max(0,s[i][i]));for(int i=0;i<size;i++)for(int j=0;j<size;j++){if(sd[i]==0||sd[j]==0){if(Math.abs(s[i][j])>1e-12)throw new IllegalArgumentException("A zero-variance disturbance has nonzero covariance.");}else normalized[i][j]=s[i][j]/sd[i]/sd[j];}for(int i=0;i<size;i++)for(int j=0;j<=i;j++){double remainder=normalized[i][j];for(int k=0;k<j;k++)remainder-=lower[i][k]*lower[j][k];if(i==j){if(remainder< -1e-10)throw new IllegalArgumentException("Population disturbance covariance is not positive semidefinite.");lower[i][j]=Math.sqrt(Math.max(0,remainder));}else if(lower[j][j]>1e-12)lower[i][j]=remainder/lower[j][j];else if(Math.abs(remainder)>1e-9)throw new IllegalArgumentException("Population disturbance factorization is numerically singular.");}for(int i=0;i<size;i++)for(int j=0;j<size;j++)lower[i][j]*=sd[i];RealMatrix h=new LUDecomposition(MatrixUtils.createRealIdentityMatrix(size).subtract(state.directed())).getSolver().getInverse();double[] observedSD=new double[p];for(int j=0;j<p;j++)observedSD[j]=Math.sqrt(state.covariance().getEntry(j,j));return new Population(h.multiply(new Array2DRowRealMatrix(lower)).getData(),state.fullMean().toArray(),model.observed(),observedSD);}
    public static SemModel.Model nominal(SemModel.Model model){List<SemModel.Parameter> parameters=new ArrayList<>();for(var p:model.parameters()){boolean variance=p.locations().stream().allMatch(l->l.kind()==SemModel.Kind.COVARIANCE&&l.row()==l.column()),directed=p.locations().stream().allMatch(l->l.kind()==SemModel.Kind.DIRECTED);double start=variance?p.scale():directed?.1*p.scale():0;if(p.lower()!=null&&start<=p.lower())start=p.upper()!=null?.5*p.lower()+.5*p.upper():p.lower()+.1*p.scale();if(p.upper()!=null&&start>=p.upper())start=p.lower()!=null?.5*p.lower()+.5*p.upper():p.upper()-.1*p.scale();parameters.add(new SemModel.Parameter(p.name(),p.locations(),start,p.scale(),p.lower(),p.upper()));}return new SemModel.Model(model.variables(),model.observed(),model.directed(),model.covariance(),model.intercepts(),parameters);}
    private static boolean compatible(SemModel.Model a,SemModel.Model b){if(!a.variables().equals(b.variables())||!Arrays.equals(a.observed(),b.observed())||a.parameters().size()!=b.parameters().size())return false;Map<String,Set<SemModel.Location>> first=new HashMap<>(),second=new HashMap<>();for(var p:a.parameters())first.put(p.name(),Set.copyOf(p.locations()));for(var p:b.parameters())second.put(p.name(),Set.copyOf(p.locations()));if(!first.equals(second))return false;return Arrays.deepEquals(fixed(a,SemModel.Kind.DIRECTED),fixed(b,SemModel.Kind.DIRECTED))&&Arrays.deepEquals(fixed(a,SemModel.Kind.COVARIANCE),fixed(b,SemModel.Kind.COVARIANCE))&&Arrays.deepEquals(fixed(a,SemModel.Kind.INTERCEPT),fixed(b,SemModel.Kind.INTERCEPT));}
    private static double[][] fixed(SemModel.Model model,SemModel.Kind kind){double[][] matrix=kind==SemModel.Kind.DIRECTED?model.directed():kind==SemModel.Kind.COVARIANCE?model.covariance():new double[][]{model.intercepts()};for(var p:model.parameters())for(var l:p.locations())if(l.kind()==kind){if(kind==SemModel.Kind.INTERCEPT)matrix[0][l.row()]=0;else{matrix[l.row()][l.column()]=0;if(kind==SemModel.Kind.COVARIANCE)matrix[l.column()][l.row()]=0;}}return matrix;}
    private static long mix(long value){value=(value^(value>>>30))*0xbf58476d1ce4e5b9L;value=(value^(value>>>27))*0x94d049bb133111ebL;return value^(value>>>31);}
    private static String digest(Trial[] trials){try{var out=MessageDigest.getInstance("SHA-256");out.update("brightstats-simulation-v1".getBytes(StandardCharsets.UTF_8));for(var trial:trials){text(out,trial.issue());number(out,trial.sampleSize());number(out,trial.replicate());number(out,trial.seed());number(out,trial.informativeRows());number(out,trial.missingCells());number(out,trial.converged()?1:0);number(out,trial.locallyIdentified()?1:0);number(out,trial.boundary()?1:0);number(out,trial.targets().size());for(var target:trial.targets()){text(out,target.parameter());number(out,Double.doubleToLongBits(target.estimate()));number(out,Double.doubleToLongBits(target.standardError()));number(out,target.covered()==null?-1:target.covered()?1:0);number(out,target.rejected()==null?-1:target.rejected()?1:0);}}return HexFormat.of().formatHex(out.digest());}catch(java.security.NoSuchAlgorithmException impossible){throw new IllegalStateException(impossible);}}
    private static void text(MessageDigest digest,String text){byte[] bytes=text.getBytes(StandardCharsets.UTF_8);number(digest,bytes.length);digest.update(bytes);}
    private static void number(MessageDigest digest,long value){digest.update(ByteBuffer.allocate(8).putLong(value).array());}
}
